python3 << 'EOF'
import csv

rows = list(csv.DictReader(open('eu_economic_data.csv')))
countries = ['Germany','France','Italy','Spain','Netherlands','Poland','Sweden']
eu = [r for r in rows if r['Country']=='EU_Total'][0]

print("=== EU TOTAL ===")
for y in ['2022','2023','2024']:
    r = [x for x in rows if x['Country']=='EU_Total' and x['Year']==y][0]
    print(y, "GDP:", r['GDP_Billion_EUR'], "| Growth:", r['GDP_Growth_Pct'], "| Unemp:", r['Unemployment_Pct'],
          "| Inf:", r['Inflation_Pct'], "| Trade:", r['Trade_Balance_Billion_EUR'], "| Debt:", r['Public_Debt_Pct_GDP'])

print("\nAvg EU growth 2023-24:", round((0.4+0.9)/2,2))
print("Cumulative nominal GDP 2022->2024: {:.1f}%".format((17655.7/15800.3-1)*100))

print("\n=== 2024 COUNTRY RANKINGS ===")
d24 = [r for r in rows if r['Year']=='2024' and r['Country']!='EU_Total']
for key,label in [('GDP_Growth_Pct','Growth'),('Unemployment_Pct','Unemp'),('Inflation_Pct','Inflation'),('Trade_Balance_Billion_EUR','Trade'),('Public_Debt_Pct_GDP','Debt')]:
    print("\n--", label, "--")
    for r in sorted(d24, key=lambda r: float(r[key])):
        print(f"  {r['Country']:<12} {r[key]}")

print("\n=== GERMANY TRADE (deficit shift) ===")
for r in rows:
    if r['Country']=='Germany':
        print(r['Year'], r['Trade_Balance_Billion_EUR'], "growth", r['GDP_Growth_Pct'])

print("\n=== SPAIN UNEMPLOYMENT PATH ===")
for r in rows:
    if r['Country']=='Spain':
        print(r['Year'], r['Unemployment_Pct'])

print("\n=== POLAND INFLATION PATH ===")
for r in rows:
    if r['Country']=='Poland':
        print(r['Year'], r['Inflation_Pct'])

print("\n=== FRANCE/ITALY DEBT ===")
for r in rows:
    if r['Country'] in ('France','Italy'):
        print(r['Country'], r['Year'], r['Public_Debt_Pct_GDP'])

print("\n=== EU TRADE PATH ===")
for r in rows:
    if r['Country']=='EU_Total':
        print(r['Year'], r['Trade_Balance_Billion_EUR'])
